      {
        "factor": "Early-2026 mortality pace (Feb 2026: ~606 deaths)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "The pace through February indicates momentum that could push total deaths past 1,000 if sustained through March–April."
      },
      {
        "factor": "Adverse weather and hazardous sea conditions in the central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Storms and rough seas increase risk and have historically produced spikes in monthly fatalities."
      },
      {
        "factor": "Seasonal migration patterns toward spring",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spring migrations typically rise, potentially elevating cumulative deaths if other conditions remain unfavorable."
      },
      {
        "factor": "Policy shifts and search-and-rescue capacity",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Tighter controls and stronger SAR could reduce crossings and fatalities, lowering observed toll."
      },
      {
